package ai.agrinexus.mapintel;
import android.app.*;import android.content.Intent;import android.os.*;import java.util.concurrent.*;
/** Separate, USB-authorized instrumentation APK; never included in MapIntel. */
public final class MapIntelProbe extends Instrumentation {
 Bundle args;
 @Override public void onCreate(Bundle b){super.onCreate(b);args=b;start();}
 String eval(MainActivity a,String script)throws Exception {CountDownLatch done=new CountDownLatch(1);String[] value={""};runOnMainSync(()->{if(a.web==null){done.countDown();return;}a.web.evaluateJavascript(script,r->{value[0]=r;done.countDown();});});if(!done.await(15,TimeUnit.SECONDS))throw new Exception("UI evaluation timed out");return value[0];}
 @Override public void onStart(){Bundle result=new Bundle();try{MainActivity a=(MainActivity)startActivitySync(new Intent(getTargetContext(),MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK|Intent.FLAG_ACTIVITY_CLEAR_TASK));String ready="";for(int i=0;i<30;i++){ready=eval(a,"document.querySelector('nav')?'ready':'waiting'");if(ready.contains("ready"))break;Thread.sleep(300);}String action=args==null?"":args.getString("action","");if(action.contains("loadingcheck")){runOnMainSync(()->{android.widget.LinearLayout panel=a.loadingPanel("Loading estate map…");android.view.ViewGroup brand=(android.view.ViewGroup)panel.getChildAt(0),logo=(android.view.ViewGroup)brand.getChildAt(0);result.putBoolean("ringAnimates",a.loadingAnimation.getTarget()==logo.getChildAt(0)&&a.loadingAnimation.isRunning());result.putBoolean("logoStationary",logo.getChildAt(1).getRotation()==0f);result.putBoolean("loadingMessage",((android.widget.TextView)panel.getChildAt(1)).getText().toString().equals("Please wait while loading"));a.stopLoadingAnimation();});}for(String step:action.split("[|]")){if(step.startsWith("select:")){String value=step.substring(7);eval(a,"(()=>{const s=document.querySelector('.analytics-choice select');if(!s)return false;const setter=Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype,'value').set;setter.call(s,"+org.json.JSONObject.quote(value)+");s.dispatchEvent(new Event('change',{bubbles:true}));return true;})()");Thread.sleep(700);}if(step.startsWith("click:")){String label=step.substring(6);eval(a,"(()=>{const name="+org.json.JSONObject.quote(label)+";const b=[...document.querySelectorAll('button')].find(b=>b.getAttribute('aria-label')===name||b.textContent.trim()===name);if(b)b.click();return !!b;})()");Thread.sleep(700);}}if(action.contains("Show my location")){for(int i=0;i<100;i++){String gps=eval(a,"document.querySelector('.osm-attribution')?'nearby-ready':'waiting'");if(gps.contains("nearby-ready"))break;Thread.sleep(400);}}String script="JSON.stringify({fertiliserRows:window.__MAPINTEL_DATA__?.fertiliser?.fertiliser?.length,fertiliserCards:[...document.querySelectorAll('[aria-label=\"Annual block fertiliser\"] .metric-grid article>span')].map(e=>e.textContent),legend:!!document.querySelector('.fertiliser-key'),ready:!!document.querySelector('nav'),headings:[...document.querySelectorAll('h2,h3')].map(e=>e.textContent).slice(0,5),tabs:[...document.querySelectorAll('nav button')].map(e=>e.textContent),connection:document.querySelector('.connection')?.textContent,imageStatus:document.querySelector('.estate-map')?.getAttribute('data-image-status'),nearby:!!document.querySelector('.osm-attribution'),canvases:document.querySelectorAll('canvas').length,images:[...document.images].map(i=>({alt:i.alt,loaded:i.complete&&i.naturalWidth>0})),headerBottom:document.querySelector('.sync-strip')?.getBoundingClientRect().bottom,contentTop:document.querySelector('.content-scroll,.map-workspace')?.getBoundingClientRect().top,navTop:document.querySelector('nav')?.getBoundingClientRect().top,bodyHeight:document.body.clientHeight,gpsNotes:!!document.querySelector('.location-status'),locationText:document.querySelector('.location-fab')?.textContent,locationBelowMap:document.querySelector('.location-fab')?.getBoundingClientRect().top>document.querySelector('.fit-fab')?.getBoundingClientRect().bottom,analyticsOptions:[...document.querySelectorAll('.analytics-choice option')].map(e=>e.textContent),toast:document.querySelector('[role=\"status\"]')?.textContent,metrics:[...document.querySelectorAll('.metric-grid strong')].map(e=>e.textContent),scrollTop:document.querySelector('.native-root')?.scrollTop})";result.putString("ui",eval(a,script));finish(Activity.RESULT_OK,result);}catch(Exception e){result.putString("error",e.getClass().getSimpleName()+": "+e.getMessage());finish(Activity.RESULT_CANCELED,result);}}
}
